// ─────────────────────────────────────────────────────────────────────────────
// Single source of truth for the Mindful Lock native (Kotlin) sources.
//
// `android/` is gitignored and regenerated by `expo prebuild`, so hand-editing
// `android/app/src/main/java/<pkg>/AppBlocker*.kt` silently loses work. Every
// change belongs HERE. `plugins/withAppBlocker.js` writes these into the
// prebuild output, and `scripts/sync-appblocker-native.js` writes the same
// content into an already-prebuilt `android/` folder so you can rebuild
// without a full prebuild.
// ─────────────────────────────────────────────────────────────────────────────

const usageUtils = (packageName) => `package ${packageName}

import android.content.SharedPreferences
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Shared helpers for tracking per-app, per-day usage time in the
 * AppBlockerPrefs SharedPreferences store. The date-scoped key means
 * usage automatically "resets" at midnight without any cron job.
 *
 * Two notions of "usage" exist:
 *   - STORED usage: whole milliseconds already banked under usage_<pkg>_<date>.
 *   - LIVE usage: stored + the in-flight slice of the session currently on
 *     screen (now - lastForegroundTimestamp). The accessibility service only
 *     banks the in-flight slice periodically, so anything that needs an
 *     accurate "right now" number (the block decision, the JS progress bar)
 *     must use the live value.
 */
object AppBlockerUsageUtils {

    // Ignore implausible jumps (phone slept, service was killed and restarted,
    // clock changed) instead of crediting hours to whatever was last on screen.
    const val MAX_SESSION_MS = 30 * 60 * 1000L // 30 minutes

    private fun todayDateString(): String {
        val sdf = SimpleDateFormat("yyyy-MM-dd", Locale.US)
        return sdf.format(Date())
    }

    fun usageKey(packageName: String): String {
        return "usage_" + packageName + "_" + todayDateString()
    }

    fun getTodayUsageMs(prefs: SharedPreferences, packageName: String): Long {
        return prefs.getLong(usageKey(packageName), 0L)
    }

    /**
     * Stored usage plus the not-yet-banked slice of the current session, if
     * [packageName] is the package currently on screen. This is what makes the
     * progress bar move second-by-second and the block fire mid-session.
     */
    fun getLiveUsageMs(prefs: SharedPreferences, packageName: String): Long {
        var used = getTodayUsageMs(prefs, packageName)
        val lastPkg = prefs.getString("lastForegroundPackage", null)
        val lastTs = prefs.getLong("lastForegroundTimestamp", 0L)
        if (lastPkg == packageName && lastTs > 0L) {
            val delta = System.currentTimeMillis() - lastTs
            if (delta > 0 && delta < MAX_SESSION_MS) used += delta
        }
        return used
    }

    fun addTodayUsage(prefs: SharedPreferences, packageName: String, ms: Long) {
        if (ms <= 0) return
        val key = usageKey(packageName)
        val current = prefs.getLong(key, 0L)
        prefs.edit().putLong(key, current + ms).apply()
    }

    /**
     * Zeroes today's counter for [packageName]. Called when an app is newly added
     * to Mindful Lock so its budget always starts from a clean slate today, even
     * if the app was tracked and then removed earlier the same day. Tomorrow's
     * key is a different date string, so this only ever affects today.
     */
    fun resetTodayUsage(prefs: SharedPreferences, packageName: String) {
        prefs.edit().remove(usageKey(packageName)).apply()
    }

    /**
     * Parses a rule entry for a package from the blockedApps JSON.
     * Supports both the new object format:
     *   { "unblockUntil": 0, "dailyBudgetMinutes": 60, "lockMode": "allowance" }
     * and the legacy plain-number format (unblockUntil only, no budget)
     * for backward compatibility with stale prefs from an older JS build.
     */
    fun parseRule(root: org.json.JSONObject, packageName: String): org.json.JSONObject {
        val raw = root.opt(packageName)
        return when (raw) {
            is org.json.JSONObject -> raw
            is Number -> org.json.JSONObject().apply {
                put("unblockUntil", raw.toLong())
                put("dailyBudgetMinutes", 0)
            }
            else -> org.json.JSONObject()
        }
    }

    fun isTracked(prefs: SharedPreferences, packageName: String): Boolean {
        val raw = prefs.getString("blockedApps", "{}") ?: "{}"
        return try {
            org.json.JSONObject(raw).has(packageName)
        } catch (e: Exception) {
            false
        }
    }

    /**
     * Should [packageName] be blocked at [now]? Mirrors the JS-side rules:
     * a temporary allowance always wins, a globally-strict effective mode
     * upgrades every app to a hard lock, otherwise an allowance app is blocked
     * once today's LIVE usage reaches its budget.
     */
    fun shouldBlock(prefs: SharedPreferences, packageName: String, now: Long): Boolean {
        val blockedAppsString = prefs.getString("blockedApps", "{}") ?: "{}"
        return try {
            val root = org.json.JSONObject(blockedAppsString)
            if (!root.has(packageName)) return false

            val rule = parseRule(root, packageName)
            val unblockUntil = rule.optLong("unblockUntil", 0L)

            // Temporary "grant N minutes" override always wins, for any lock mode.
            if (now < unblockUntil) return false

            // Strict mode does NOT skip the allowance.
            //
            // This used to read:
            //     if (getEffectiveMode(prefs) == "strict") "hard" else perAppLockMode
            // which made a globally-strict profile block every app on sight and
            // rendered the per-app daily budget meaningless — you could set "1
            // minute" and never get a single second.
            //
            // Strict is about whether you can TALK YOUR WAY OUT, not whether you
            // get your time. Both modes spend the same allowance; when it runs
            // out, CBT lets you reflect and grant yourself more minutes while
            // strict offers no override at all (BlockedAppScreen hides the grant
            // buttons when the mode is strict).
            //
            // A per-app lockMode of "hard" still means always-blocked: that is an
            // explicit per-app choice rather than a global mode.
            val lockMode = rule.optString("lockMode", "allowance")
            val dailyBudgetMinutes = rule.optInt("dailyBudgetMinutes", 0)

            when (lockMode) {
                "hard" -> true // Hard lock mode: always block, no allowance
                else -> {
                    // Allowance mode: block once today's usage meets/exceeds the
                    // budget. A budget of 0 or less means "no allowance
                    // configured" -> always block.
                    if (dailyBudgetMinutes <= 0) {
                        true
                    } else {
                        getLiveUsageMs(prefs, packageName) >= dailyBudgetMinutes * 60_000L
                    }
                }
            }
        } catch (e: Exception) {
            false
        }
    }

    fun getEffectiveMode(prefs: SharedPreferences): String {
        val raw = prefs.getString("scheduleConfig", null) ?: return "cbt"
        try {
            val root = org.json.JSONObject(raw)
            val baseMode = root.optString("baseMode", "cbt")
            val schedules = root.optJSONArray("schedules") ?: return baseMode

            val cal = java.util.Calendar.getInstance()
            val day = cal.get(java.util.Calendar.DAY_OF_WEEK) - 1
            val nowMinutes = cal.get(java.util.Calendar.HOUR_OF_DAY) * 60 + cal.get(java.util.Calendar.MINUTE)

            var sawActiveStrict = false
            var sawActiveAny = false

            for (i in 0 until schedules.length()) {
                val s = schedules.optJSONObject(i) ?: continue
                if (!s.optBoolean("enabled", true)) continue

                val days = s.optJSONArray("days")
                if (days != null && days.length() > 0) {
                    var dayMatches = false
                    for (j in 0 until days.length()) {
                        if (days.optInt(j, -1) == day) { dayMatches = true; break }
                    }
                    if (!dayMatches) continue
                }

                val start = s.optString("start", "")
                val end = s.optString("end", "")
                if (start.isEmpty() || end.isEmpty()) continue

                val startParts = start.split(":")
                val endParts = end.split(":")
                if (startParts.size != 2 || endParts.size != 2) continue

                val startMinutes = (startParts[0].toIntOrNull() ?: continue) * 60 + (startParts[1].toIntOrNull() ?: continue)
                val endMinutes = (endParts[0].toIntOrNull() ?: continue) * 60 + (endParts[1].toIntOrNull() ?: continue)
                if (startMinutes == endMinutes) continue

                val isActive = if (startMinutes < endMinutes) {
                    nowMinutes >= startMinutes && nowMinutes < endMinutes
                } else {
                    nowMinutes >= startMinutes || nowMinutes < endMinutes
                }

                if (isActive) {
                    sawActiveAny = true
                    if (s.optString("mode", "cbt") == "strict") sawActiveStrict = true
                }
            }

            return when {
                sawActiveStrict -> "strict"
                sawActiveAny -> "cbt"
                else -> baseMode
            }
        } catch (e: Exception) {
            return "cbt"
        }
    }
}
`;

const service = (packageName) => `package ${packageName}

import android.accessibilityservice.AccessibilityService
import android.view.accessibility.AccessibilityEvent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.content.SharedPreferences
import android.net.Uri
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.provider.Settings

// How often we re-check the budget while a tracked app is on screen. This is
// the ONLY thing that can block mid-session — accessibility events alone fire
// on app switches, so without this ticker a user could scroll for an hour
// inside their allowance app and never be interrupted.
private const val TICK_MS = 1000L

// The ticker also runs while an UNTRACKED app is on screen, more slowly, purely
// so it can notice a switch that produced no accessibility event. Some apps and
// launchers never emit TYPE_WINDOW_STATE_CHANGED when you return to them, which
// left the tracker pointing at the previous app and stopped counting entirely —
// the "sometimes it counts, sometimes it ignores" behaviour. Every tick now
// re-reads the real foreground package instead of trusting the last event.
private const val IDLE_TICK_MS = 5000L

// The ticker checks LIVE usage (which needs no write), and only banks the
// elapsed slice to disk this often, so a service restart loses at most this
// much time instead of the whole session.
private const val FLUSH_INTERVAL_MS = 15_000L

// After firing a block, wait this long before firing again for the same
// foreground app. Without a cooldown the block screen's own window events
// (and any failed launch) would retrigger in a tight loop.
private const val BLOCK_COOLDOWN_MS = 5_000L

class AppBlockerAccessibilityService : AccessibilityService() {

    private val handler = Handler(Looper.getMainLooper())
    private var screenOff = false
    private var lastFlushAt = 0L

    private val prefs: SharedPreferences
        get() = applicationContext.getSharedPreferences("AppBlockerPrefs", Context.MODE_PRIVATE)

    private val ticker = object : Runnable {
        override fun run() {
            try {
                onTick()
            } catch (e: Exception) {
                // Never let a bad tick kill the service.
            }
        }
    }

    private val screenReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            when (intent?.action) {
                Intent.ACTION_SCREEN_OFF -> onScreenOff()
                Intent.ACTION_SCREEN_ON, Intent.ACTION_USER_PRESENT -> onScreenOn()
            }
        }
    }

    override fun onServiceConnected() {
        super.onServiceConnected()
        val filter = IntentFilter().apply {
            addAction(Intent.ACTION_SCREEN_OFF)
            addAction(Intent.ACTION_SCREEN_ON)
            addAction(Intent.ACTION_USER_PRESENT)
        }
        try {
            // SCREEN_ON/OFF/USER_PRESENT are protected system broadcasts, so they
            // are exempt from the Android 14 exported-flag requirement.
            registerReceiver(screenReceiver, filter)
        } catch (e: Exception) {
        }
        // The service can be (re)connected while an app is already on screen —
        // no window event will arrive for it, so seed the tracker ourselves.
        adoptCurrentForegroundApp()
        // Guarantee the ticker is alive even if adopt found nothing (no active
        // window yet at connect time). Without this the service would sit idle
        // until the first accessibility event arrived.
        startTicker(IDLE_TICK_MS)
    }

    override fun onDestroy() {
        handler.removeCallbacks(ticker)
        try {
            unregisterReceiver(screenReceiver)
        } catch (e: Exception) {
        }
        // Bank whatever was in flight so it isn't lost.
        try {
            creditPendingUsage(System.currentTimeMillis())
        } catch (e: Exception) {
        }
        super.onDestroy()
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event == null || event.eventType != AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED) return
        val packageName = event.packageName?.toString() ?: return

        val now = System.currentTimeMillis()

        // Bank the slice that just elapsed. We do this for SAME-package events
        // too: an in-app dialog, keyboard or navigation used to reset the
        // stopwatch to zero, so long sessions were massively under-counted and
        // the budget was never reached.
        creditPendingUsage(now)
        lastFlushAt = now

        // Always move the tracker, even for our own package. Previously we
        // returned early for LifePilot, which left the previous app marked as
        // "foreground" and kept crediting it time while the user sat in
        // LifePilot.
        prefs.edit()
            .putString("lastForegroundPackage", packageName)
            .putLong("lastForegroundTimestamp", now)
            .apply()

        // The ticker keeps running whatever is on screen. It used to be cancelled
        // for LifePilot and for untracked apps, which meant the only thing that
        // could ever restart it was another accessibility event — so a switch that
        // fired no event left the service permanently blind until the next one.
        // onTick() re-reads the foreground app itself and paces itself, so leaving
        // it alive is both correct and cheap.
        if (packageName == applicationContext.packageName) {
            startTicker(IDLE_TICK_MS)
            return
        }

        if (AppBlockerUsageUtils.isTracked(prefs, packageName)) {
            enforce(packageName, now)
            startTicker(TICK_MS)
        } else {
            startTicker(IDLE_TICK_MS)
        }
    }

    override fun onInterrupt() {}

    // ── Ticker ───────────────────────────────────────────────────────────────

    private fun startTicker(delayMs: Long = TICK_MS) {
        handler.removeCallbacks(ticker)
        if (screenOff) return
        handler.postDelayed(ticker, delayMs)
    }

    /** The package that genuinely owns the active window right now, or null. */
    private fun currentForegroundPackage(): String? {
        return try {
            rootInActiveWindow?.packageName?.toString()
        } catch (e: Exception) {
            null
        }
    }

    /**
     * Runs while the screen is on and NEVER stops itself, because stopping is how
     * the service used to go blind.
     *
     * Previously this bailed out whenever the tracked package was LifePilot or
     * untracked, and it trusted the stored lastForegroundPackage — a value only
     * written by an accessibility event. If you went blocked-app → LifePilot →
     * blocked-app and the return produced no TYPE_WINDOW_STATE_CHANGED (common:
     * the activity was resumed rather than recreated), the tracker stayed on
     * LifePilot, the ticker stayed cancelled, and the session was never counted
     * or enforced.
     *
     * Now every tick resolves the real foreground package itself and rebases the
     * tracker if it has drifted, so a missed event self-heals within one tick.
     */
    private fun onTick() {
        if (screenOff) return

        val p = prefs
        val now = System.currentTimeMillis()
        val actual = currentForegroundPackage()
        val trackedPkg = p.getString("lastForegroundPackage", null)

        if (actual != null && actual != trackedPkg) {
            // A switch we were never told about. Bank what the previous app owed,
            // then adopt the new one.
            creditPendingUsage(now)
            p.edit()
                .putString("lastForegroundPackage", actual)
                .putLong("lastForegroundTimestamp", now)
                .apply()
            lastFlushAt = now
        } else if (now - lastFlushAt >= FLUSH_INTERVAL_MS) {
            // Same app still on screen: bank periodically so a service restart
            // loses at most FLUSH_INTERVAL_MS rather than the whole session.
            creditPendingUsage(now)
            lastFlushAt = now
        }

        val current = actual ?: trackedPkg
        val isOurs = current == null || current == applicationContext.packageName
        val isTracked = current != null && !isOurs && AppBlockerUsageUtils.isTracked(p, current)

        if (isTracked) enforce(current!!, now)

        // Poll fast while a tracked app is on screen (the budget has to be able
        // to expire mid-scroll), slowly otherwise (only watching for a switch).
        handler.postDelayed(ticker, if (isTracked) TICK_MS else IDLE_TICK_MS)
    }

    // ── Usage accounting ─────────────────────────────────────────────────────

    /**
     * Banks (now - lastForegroundTimestamp) against whatever package is
     * currently marked as foreground, then rebases the timestamp so the same
     * slice can't be counted twice.
     */
    private fun creditPendingUsage(now: Long) {
        val p = prefs
        val lastPkg = p.getString("lastForegroundPackage", null) ?: return
        val lastTs = p.getLong("lastForegroundTimestamp", 0L)
        if (lastTs <= 0L) return

        val elapsed = now - lastTs
        // Only TRACKED apps accrue usage.
        //
        // This used to bank time against whatever was last on screen, tracked or
        // not, so every app the user opened all day accumulated a usage_<pkg>_<date>
        // counter. The moment an app was added to Mindful Lock it inherited that
        // history, and a fresh "1 minute" budget was already spent — the block
        // screen fired on the very first open. It also made the in-app progress bar
        // start full, which looked like the live usage readout was broken.
        //
        // Untracked apps are none of our business anyway: not measuring them is
        // both the correct behaviour and less data collected.
        if (elapsed > 0 &&
            elapsed < AppBlockerUsageUtils.MAX_SESSION_MS &&
            lastPkg != applicationContext.packageName &&
            AppBlockerUsageUtils.isTracked(p, lastPkg)
        ) {
            AppBlockerUsageUtils.addTodayUsage(p, lastPkg, elapsed)
        }
        p.edit().putLong("lastForegroundTimestamp", now).apply()
    }

    private fun onScreenOff() {
        screenOff = true
        handler.removeCallbacks(ticker)
        val now = System.currentTimeMillis()
        try {
            creditPendingUsage(now)
        } catch (e: Exception) {
        }
        // Clear the tracker: no window events fire while the screen is off, so
        // leaving it set would credit the whole sleep to the last app used.
        prefs.edit()
            .remove("lastForegroundPackage")
            .remove("lastForegroundTimestamp")
            .apply()
    }

    private fun onScreenOn() {
        screenOff = false
        adoptCurrentForegroundApp()
        // adoptCurrentForegroundApp() only starts the ticker when it lands on a
        // tracked app. Unlocking onto the launcher or an untracked app must still
        // leave the service watching, or the next switch can go unnoticed.
        startTicker(IDLE_TICK_MS)
    }

    /**
     * Reads the package that owns the active window and treats it as a fresh
     * foreground session. Used on service connect and on screen-on, where no
     * TYPE_WINDOW_STATE_CHANGED is guaranteed to arrive.
     */
    private fun adoptCurrentForegroundApp() {
        val pkg = try {
            rootInActiveWindow?.packageName?.toString()
        } catch (e: Exception) {
            null
        } ?: return

        if (pkg == applicationContext.packageName) return

        val now = System.currentTimeMillis()
        prefs.edit()
            .putString("lastForegroundPackage", pkg)
            .putLong("lastForegroundTimestamp", now)
            .apply()
        lastFlushAt = now

        if (AppBlockerUsageUtils.isTracked(prefs, pkg)) {
            enforce(pkg, now)
            startTicker()
        }
    }

    // ── Enforcement ──────────────────────────────────────────────────────────

    private fun enforce(packageName: String, now: Long) {
        if (!AppBlockerUsageUtils.shouldBlock(prefs, packageName, now)) return

        // Cooldown is PER PACKAGE. A single global stamp meant blocking one app
        // suppressed the block for every other app for the same window, so the
        // second distracting app opened inside that window went unenforced.
        val cooldownKey = "lastBlockTriggerAt_" + packageName
        val lastTrigger = prefs.getLong(cooldownKey, 0L)
        if (now - lastTrigger < BLOCK_COOLDOWN_MS) return
        prefs.edit().putLong(cooldownKey, now).apply()

        launchBlockScreen(packageName)
    }

    /**
     * Android 10+ forbids background activity starts unless the app is exempt.
     * The exemption we can actually obtain is the "Display over other apps"
     * (SYSTEM_ALERT_WINDOW) app-op. Without it startActivity() is dropped
     * SILENTLY — no exception — which is why the block screen never appeared.
     */
    private fun canStartActivityFromBackground(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return true
        return try {
            Settings.canDrawOverlays(applicationContext)
        } catch (e: Exception) {
            false
        }
    }

    private fun buildBlockIntent(packageName: String): Intent {
        // ACTION_VIEW deep link so React Navigation routes to the BlockedApp
        // screen. (Intent extras are NOT read by RN Linking.)
        //
        // 't' is a one-shot token. Starting this with FLAG_ACTIVITY_NEW_TASK makes
        // the deep link the BASE INTENT of LifePilot's task, so Android replays it
        // every time the user later reopens LifePilot from the launcher or recents
        // — they landed back on the block screen instead of their dashboard, no
        // matter how cleanly the screen dismissed itself. BlockedAppScreen records
        // the token it has handled and bounces any repeat to the dashboard, so a
        // replayed base intent is inert while a genuinely new block still shows.
        val blockUri = Uri.parse(
            "lifepilot://blocked?app=" + Uri.encode(packageName) +
                "&t=" + System.currentTimeMillis()
        )
        return Intent(Intent.ACTION_VIEW, blockUri).apply {
            setPackage(applicationContext.packageName)
            addFlags(
                Intent.FLAG_ACTIVITY_NEW_TASK or
                    Intent.FLAG_ACTIVITY_CLEAR_TOP or
                    Intent.FLAG_ACTIVITY_SINGLE_TOP
            )
            putExtra("blocked_app", packageName)
        }
    }

    private fun startBlockActivity(packageName: String) {
        try {
            startActivity(buildBlockIntent(packageName))
        } catch (e: Exception) {
            val launchIntent = packageManager.getLaunchIntentForPackage(applicationContext.packageName)
            if (launchIntent != null) {
                launchIntent.addFlags(
                    Intent.FLAG_ACTIVITY_NEW_TASK or
                        Intent.FLAG_ACTIVITY_CLEAR_TOP or
                        Intent.FLAG_ACTIVITY_SINGLE_TOP
                )
                launchIntent.putExtra("blocked_app", packageName)
                try {
                    startActivity(launchIntent)
                } catch (e2: Exception) {
                }
            }
        }
    }

    private fun launchBlockScreen(packageName: String) {
        if (canStartActivityFromBackground()) {
            startBlockActivity(packageName)
            return
        }

        // No overlay permission: our activity start would be swallowed. Still
        // enforce the lock by sending the user Home (an accessibility service
        // can always do this), then try the deep link once the distracting app
        // is off screen.
        try {
            performGlobalAction(GLOBAL_ACTION_HOME)
        } catch (e: Exception) {
        }
        handler.postDelayed({ startBlockActivity(packageName) }, 400L)
    }
}
`;

const nativeModule = (packageName) => `package ${packageName}

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.provider.Settings
import android.text.TextUtils
import android.view.accessibility.AccessibilityManager
import android.accessibilityservice.AccessibilityServiceInfo
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.facebook.react.bridge.Promise

class AppBlockerModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {

    private val prefs
        get() = reactApplicationContext.getSharedPreferences("AppBlockerPrefs", Context.MODE_PRIVATE)

    override fun getName(): String {
        return "AppBlocker"
    }

    @ReactMethod
    fun isAccessibilityServiceEnabled(promise: Promise) {
        try {
            val am = reactApplicationContext.getSystemService(Context.ACCESSIBILITY_SERVICE) as AccessibilityManager
            val enabledServices = am.getEnabledAccessibilityServiceList(AccessibilityServiceInfo.FEEDBACK_ALL_MASK)

            for (service in enabledServices) {
                val componentName = service.resolveInfo.serviceInfo
                if (componentName.packageName == reactApplicationContext.packageName &&
                    componentName.name.contains("AppBlockerAccessibilityService", ignoreCase = true)) {
                    promise.resolve(true)
                    return
                }
            }
            promise.resolve(false)
        } catch (e: Exception) {
            promise.resolve(false)
        }
    }

    @ReactMethod
    fun openAccessibilitySettings() {
        val intent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        reactApplicationContext.startActivity(intent)
    }

    /**
     * "Display over other apps". Required on Android 10+ for the accessibility
     * service to be allowed to foreground the block screen from the background —
     * without it the launch is dropped silently and nothing appears to happen.
     */
    @ReactMethod
    fun hasOverlayPermission(promise: Promise) {
        try {
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
                promise.resolve(true)
                return
            }
            promise.resolve(Settings.canDrawOverlays(reactApplicationContext))
        } catch (e: Exception) {
            promise.resolve(false)
        }
    }

    @ReactMethod
    fun requestOverlayPermission() {
        try {
            val intent = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
                Intent(
                    Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                    Uri.parse("package:" + reactApplicationContext.packageName)
                )
            } else {
                Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                    Uri.parse("package:" + reactApplicationContext.packageName))
            }
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            reactApplicationContext.startActivity(intent)
        } catch (e: Exception) {
            try {
                val fallback = Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION)
                fallback.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                reactApplicationContext.startActivity(fallback)
            } catch (e2: Exception) {
            }
        }
    }

    @ReactMethod
    fun updateBlockedApps(appsStr: String) {
        prefs.edit().putString("blockedApps", appsStr).apply()
    }

    @ReactMethod
    fun updateSchedules(schedulesJson: String) {
        prefs.edit().putString("scheduleConfig", schedulesJson).apply()
    }

    /**
     * Clears today's accrued usage for one package.
     *
     * Called when an app is newly added to Mindful Lock. Usage now only accrues
     * for tracked apps, but an app that was tracked, removed, and re-added the
     * same day would otherwise inherit its earlier total and blow a fresh budget
     * immediately. Adding an app should always give it a full allowance today.
     */
    @ReactMethod
    fun resetUsage(packageName: String) {
        try {
            AppBlockerUsageUtils.resetTodayUsage(prefs, packageName)
        } catch (e: Exception) {
        }
    }

    /** LIVE usage in ms: banked time plus the in-flight slice of the session on screen. */
    @ReactMethod
    fun getUsageToday(packageName: String, promise: Promise) {
        try {
            promise.resolve(AppBlockerUsageUtils.getLiveUsageMs(prefs, packageName).toDouble())
        } catch (e: Exception) {
            promise.resolve(0.0)
        }
    }

    /**
     * Batched version of [getUsageToday]. Takes a JSON array of package names
     * and returns a JSON object of { packageName: liveUsageMs }, so the UI can
     * poll every second with a single bridge round-trip instead of one per app.
     */
    @ReactMethod
    fun getUsageSnapshot(packagesJson: String, promise: Promise) {
        try {
            val p = prefs
            val requested = org.json.JSONArray(packagesJson)
            val out = org.json.JSONObject()
            for (i in 0 until requested.length()) {
                val pkg = requested.optString(i, "")
                if (pkg.isEmpty()) continue
                out.put(pkg, AppBlockerUsageUtils.getLiveUsageMs(p, pkg))
            }
            promise.resolve(out.toString())
        } catch (e: Exception) {
            promise.resolve("{}")
        }
    }

    // Lists the apps the user could plausibly want to restrict, for the Mindful
    // Lock picker.
    //
    // WHY queryIntentActivities AND NOT getInstalledApplications
    //   getInstalledApplications() returns every installed package, which on
    //   Android 11+ only works with QUERY_ALL_PACKAGES. Play restricts that
    //   permission to a short list of use cases — device search, antivirus, file
    //   managers, browsers, enterprise management — and an app blocker is not one
    //   of them, so shipping it invites rejection.
    //
    //   Resolving ACTION_MAIN/CATEGORY_LAUNCHER instead stays inside the package
    //   visibility granted by the <queries> element withAppBlocker.js adds, so no
    //   permission is required. It also gives a better list: only apps the user
    //   can actually open, rather than hundreds of background system packages.
    @ReactMethod
    fun getInstalledApps(promise: Promise) {
        try {
            val pm = reactApplicationContext.packageManager
            val launcherIntent = android.content.Intent(android.content.Intent.ACTION_MAIN)
                .addCategory(android.content.Intent.CATEGORY_LAUNCHER)
            val resolved = pm.queryIntentActivities(launcherIntent, 0)
            val jsonArray = org.json.JSONArray()
            // An app may expose several launcher activities; the picker wants one
            // row per app, so keep the first and drop the rest.
            val seen = HashSet<String>()
            for (info in resolved) {
                val pkg = info.activityInfo?.packageName ?: continue
                if (pkg == reactApplicationContext.packageName) continue
                if (!seen.add(pkg)) continue

                val jsonObj = org.json.JSONObject()
                jsonObj.put("packageName", pkg)
                jsonObj.put("name", info.loadLabel(pm).toString())

                try {
                    val iconDrawable = info.loadIcon(pm)
                    val w = if (iconDrawable.intrinsicWidth > 0) iconDrawable.intrinsicWidth else 1
                    val h = if (iconDrawable.intrinsicHeight > 0) iconDrawable.intrinsicHeight else 1
                    val bitmap = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                    val canvas = android.graphics.Canvas(bitmap)
                    iconDrawable.setBounds(0, 0, canvas.width, canvas.height)
                    iconDrawable.draw(canvas)
                    val stream = java.io.ByteArrayOutputStream()
                    bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, stream)
                    val base64 = android.util.Base64.encodeToString(stream.toByteArray(), android.util.Base64.NO_WRAP)
                    jsonObj.put("icon", base64)
                } catch (e: Exception) {
                    jsonObj.put("icon", "")
                }

                jsonArray.put(jsonObj)
            }
            promise.resolve(jsonArray.toString())
        } catch (e: Exception) {
            promise.reject("Error", e.message)
        }
    }
}
`;

const reactPackage = (packageName) => `package ${packageName}

import com.facebook.react.ReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.uimanager.ViewManager

class AppBlockerPackage : ReactPackage {
    override fun createNativeModules(reactContext: ReactApplicationContext): List<NativeModule> {
        return listOf(AppBlockerModule(reactContext))
    }

    override fun createViewManagers(reactContext: ReactApplicationContext): List<ViewManager<*, *>> {
        return emptyList()
    }
}
`;

const ACCESSIBILITY_SERVICE_CONFIG = `<?xml version="1.0" encoding="utf-8"?>
<accessibility-service xmlns:android="http://schemas.android.com/apk/res/android"
    android:accessibilityEventTypes="typeWindowStateChanged"
    android:accessibilityFeedbackType="feedbackGeneric"
    android:accessibilityFlags="flagDefault|flagRetrieveInteractiveWindows"
    android:canRetrieveWindowContent="true"
    android:notificationTimeout="0"
    android:description="@string/app_name" />
`;

/**
 * Returns { 'AppBlockerX.kt': '<kotlin source>' } for the given Android
 * package name.
 */
const kotlinSources = (packageName) => ({
  'AppBlockerUsageUtils.kt': usageUtils(packageName),
  'AppBlockerAccessibilityService.kt': service(packageName),
  'AppBlockerModule.kt': nativeModule(packageName),
  'AppBlockerPackage.kt': reactPackage(packageName),
});

module.exports = { kotlinSources, ACCESSIBILITY_SERVICE_CONFIG };
